+func mapPlannedTasks(
+	values []*reasoningv1.PlannedTask,
+	request TaskPlanningRequest,
+	known map[string]struct{},
+) ([]PlannedTask, map[string]int, error) {
+	assigned := make(map[string]int)
+	tasks := make([]PlannedTask, 0, len(values))
